WITH kept_keys AS (SELECT promo_code FROM promotions EXCEPT SELECT promo_code FROM promotions WHERE promo_code IN ('WELCOME5', 'VIP')), verified AS (SELECT s.* FROM promotions s JOIN kept_keys k ON s.promo_code = k.promo_code), enriched AS (SELECT *, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) discount_pct_share, DENSE_RANK() OVER (ORDER BY discount_pct DESC) discount_pct_dense_rank, DENSE_RANK() OVER (ORDER BY discount_pct) discount_pct_dense_rank_2 FROM verified), with_window AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM enriched a JOIN promotions pr ON COALESCE(a.channel, 'store') = pr.channel AND a.starts_on >= pr.starts_on AND a.starts_on <= DATE_ADD(pr.ends_on, 7)), wide AS (SELECT * FROM (SELECT channel, promotion_promo_code, discount_pct_dense_rank_2 FROM with_window) src PIVOT (AVG(discount_pct_dense_rank_2) AS value_sum FOR promotion_promo_code IN ('VIP' AS vip, 'BUNDLE' AS bundle, 'WELCOME5' AS welcome5))) SELECT channel, vip, welcome5 FROM wide ORDER BY vip DESC;
